<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { useRoute } from 'vue-router';
import { api, fromApi } from '@/lib/api';
const route = useRoute(), token = String(route.params.token);
const terms = ref<string[]>([]), rooms = ref<{id:string;label:string;identifier:string;housingUnit:string;monthlyPrice:number}[]>([]);
const error=ref(''), done=ref(false), loading=ref(true), agreed=ref(false);
const fields: {k:string;l:string;t?:string;r?:boolean}[] = [{k:'firstName',l:'First name',r:true},{k:'middleName',l:'Middle name'},{k:'lastName',l:'Last name',r:true},{k:'phone',l:'Invited phone number',r:true},{k:'gender',l:'Gender'},{k:'dateOfBirth',l:'Date of birth',t:'date'},{k:'altPhone',l:'Alternative phone'},{k:'email',l:'Email',t:'email'},{k:'homeDistrict',l:'Home district'},{k:'homeAddress',l:'Home address'},{k:'institution',l:'Institution'},{k:'programme',l:'Programme'},{k:'faculty',l:'Faculty'},{k:'department',l:'Department'},{k:'yearOfStudy',l:'Year of study',t:'number'},{k:'regNumber',l:'Registration number'},{k:'academicYear',l:'Academic year'},{k:'emergencyContactName',l:'Emergency contact name'},{k:'emergencyContactPhone',l:'Emergency contact phone'},{k:'emergencyContactRelationship',l:'Relationship'}];
const form=reactive<Record<string, any>>({firstName:'',middleName:'',lastName:'',phone:'',gender:'',dateOfBirth:'',altPhone:'',email:'',homeDistrict:'',homeAddress:'',emergencyContactName:'',emergencyContactPhone:'',emergencyContactRelationship:'',institution:'',programme:'',faculty:'',department:'',yearOfStudy:'',regNumber:'',academicYear:'',preferredRoomId:''});
onMounted(async()=>{try{const data=fromApi<{terms:string[];rooms:typeof rooms.value}>(await api.get(`/public/hostel-registration/${token}`));terms.value=data.terms;rooms.value=data.rooms;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}});
async function submit(){error.value='';try{await api.post(`/public/hostel-registration/${token}`,{...form,yearOfStudy:form.yearOfStudy?Number(form.yearOfStudy):undefined,agreed});done.value=true;}catch(e){error.value=(e as Error).message;}}
</script>
<template><main class="mx-auto max-w-3xl space-y-5 p-5"><header><h1 class="text-2xl font-semibold">Hostel registration</h1><p class="text-ink-muted">Complete your details. Hostel management will review your application and allocate a room.</p></header><p v-if="loading">Loading registration…</p><section v-else-if="done" class="panel">Application submitted. Hostel management will contact you after reviewing your details and room allocation.</section><form v-else-if="!error" class="panel space-y-4" @submit.prevent="submit"><div class="grid gap-3 sm:grid-cols-2"><label v-for="field in fields" :key="field.k" class="field">{{field.l}}<input v-model="form[field.k]" class="input" :type="field.t||'text'" :required="field.r" /></label><label class="field sm:col-span-2">Preferred room (optional)<select v-model="form.preferredRoomId" class="input"><option value="">No preference</option><option v-for="room in rooms" :key="room.id" :value="room.id">{{room.housingUnit}} · {{room.label||room.identifier}} · MWK {{room.monthlyPrice.toLocaleString()}} / month</option></select><small>Final room and rent are set by hostel management.</small></label></div><section class="rounded border border-line p-4"><h2 class="font-semibold">Accommodation terms</h2><ol class="list-decimal space-y-2 pl-5"><li v-for="term in terms" :key="term">{{term}}</li></ol><label class="mt-4 flex gap-2"><input v-model="agreed" type="checkbox" required />I have read and agree to these terms. I understand my application requires management approval.</label></section><p v-if="error" class="error">{{error}}</p><button class="btn" :disabled="!agreed">Submit registration</button></form><p v-if="error && !loading" class="error">{{error}}</p></main></template>
